<?php $page_title='Profil';include 'partials/header.php';require_login();$uid=$_SESSION['user']['id'];$msg='';$st=$conn->prepare('SELECT * FROM users WHERE id=?');$st->bind_param('i',$uid);$st->execute();$u=$st->get_result()->fetch_assoc();if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$phone=trim($_POST['phone']);$address=trim($_POST['address']);$up=$conn->prepare('UPDATE users SET name=?,phone=?,address=? WHERE id=?');$up->bind_param('sssi',$name,$phone,$address,$uid);$up->execute();$_SESSION['user']['name']=$name;$msg='Profil berhasil diperbarui.';$u['name']=$name;$u['phone']=$phone;$u['address']=$address;}?><section class="auth panel"><h2>Profil Saya</h2><?php if($msg):?><div class="alert success"><?=$msg?></div><?php endif;?><form method="post"><div class="form-group"><label>Nama</label><input class="input" name="name" value="<?=htmlspecialchars($u['name'])?>"></div><div class="form-group"><label>Email</label><input class="input" value="<?=htmlspecialchars($u['email'])?>" disabled></div><div class="form-group"><label>No. HP</label><input class="input" name="phone" value="<?=htmlspecialchars($u['phone']??'')?>"></div><div class="form-group"><label>Alamat</label><textarea name="address"><?=htmlspecialchars($u['address']??'')?></textarea></div><button class="btn">Simpan</button></form></section><?php include 'partials/footer.php';?>
